public class StringReverser {
    // Approach 1: StringBuilder (recommended)
    public static String reverseWithBuilder(String input) {
        if (input == null || input.isEmpty()) return input;
        return new StringBuilder(input).reverse().toString();
    }

    // Approach 2: Manual iteration (educational)
    public static String reverseManually(String input) {
        if (input == null || input.isEmpty()) return input;
        var builder = new StringBuilder(input.length());
        for (int i = input.length() - 1; i >= 0; i--) {
            builder.append(input.charAt(i)); // iterate backwards
        }
        return builder.toString();
    }

    public static void main(String[] args) {
        var original = "Java Developer";
        System.out.println(reverseWithBuilder(original));  // repoleveD avaJ
        System.out.println(reverseManually(original));     // repoleveD avaJ
    }
}

import java.util.*;

public class CharacterFrequency {
    // Approach 1: HashMap (handles any character)
    public static Map<Character, Integer> countWithHashMap(String input) {
        var frequencyMap = new HashMap<Character, Integer>();
        for (char c : input.toCharArray()) {
            frequencyMap.merge(c, 1, Integer::sum); // increment or initialize
        }
        return frequencyMap;
    }

    // Approach 2: Array (only lowercase a-z)
    public static int[] countWithArray(String input) {
        var frequency = new int[26];
        for (char c : input.toLowerCase().toCharArray()) {
            if (c >= 'a' && c <= 'z') {
                frequency[c - 'a']++; // map a=0, b=1, ..., z=25
            }
        }
        return frequency;
    }

    public static void main(String[] args) {
        var text = "success";
        System.out.println(countWithHashMap(text));  // {s=3, u=1, c=2, e=1}
    }
}

import java.util.*;

public class AnagramChecker {
    // Approach 1: Sorting (simpler code, O(n log n))
    public static boolean isAnagramSort(String s1, String s2) {
        if (s1.length() != s2.length()) return false; // early exit
        var chars1 = s1.toLowerCase().toCharArray();
        var chars2 = s2.toLowerCase().toCharArray();
        Arrays.sort(chars1);
        Arrays.sort(chars2);
        return Arrays.equals(chars1, chars2);
    }

    // Approach 2: Frequency count (faster, O(n))
    public static boolean isAnagramFrequency(String s1, String s2) {
        if (s1.length() != s2.length()) return false;
        var frequency = new HashMap<Character, Integer>();
        for (char c : s1.toLowerCase().toCharArray()) {
            frequency.merge(c, 1, Integer::sum);
        }
        for (char c : s2.toLowerCase().toCharArray()) {
            frequency.merge(c, -1, Integer::sum); // decrement
            if (frequency.get(c) == 0) frequency.remove(c);
        }
        return frequency.isEmpty(); // all counts should be zero
    }
}

import java.util.*;

public class FirstNonRepeating {
    // Two-pass approach (recommended)
    public static Character findFirstNonRepeating(String input) {
        if (input == null || input.isEmpty()) return null;

        // Pass 1: count frequencies
        var frequency = new HashMap<Character, Integer>();
        for (char c : input.toCharArray()) {
            frequency.merge(c, 1, Integer::sum);
        }

        // Pass 2: find first with count 1
        for (char c : input.toCharArray()) {
            if (frequency.get(c) == 1) return c;
        }
        return null; // all characters repeat
    }

    // Array optimization for lowercase only
    public static Character findFirstNonRepeatingArray(String input) {
        var frequency = new int[26];
        for (char c : input.toLowerCase().toCharArray()) {
            frequency[c - 'a']++;
        }
        for (char c : input.toLowerCase().toCharArray()) {
            if (frequency[c - 'a'] == 1) return c;
        }
        return null;
    }
}

import java.util.*;
import java.util.stream.*;

public class DuplicateRemover {
    // Approach 1: LinkedHashSet (recommended)
    public static String removeDuplicatesSet(String input) {
        if (input == null || input.isEmpty()) return input;
        var uniqueChars = new LinkedHashSet<Character>();
        for (char c : input.toCharArray()) {
            uniqueChars.add(c); // duplicates ignored, order preserved
        }
        return uniqueChars.stream()
            .map(String::valueOf)
            .collect(Collectors.joining());
    }

    // Approach 2: StringBuilder with contains (O(n²) but simple)
    public static String removeDuplicatesBuilder(String input) {
        if (input == null || input.isEmpty()) return input;
        var result = new StringBuilder();
        for (char c : input.toCharArray()) {
            if (result.indexOf(String.valueOf(c)) == -1) { // O(n) check
                result.append(c);
            }
        }
        return result.toString();
    }

    public static void main(String[] args) {
        var input = "programming";
        System.out.println(removeDuplicatesSet(input));     // progamin
        System.out.println(removeDuplicatesBuilder(input)); // progamin
    }
}
